/** `licence_keys` of Sylphx Money: Resource type `money.sylphx.com/LicenceKey`. */
export class LicenceKeysCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Generates a licence key: Money creates the Ed25519 key, seals it, and never
	 * returns the private half. Needs the approval-class scope, which the developer
	 * role does not hold.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*}/licence_keys:generate` · permission `billing:licence_keys.approve` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `UNKNOWN_FIELD`, `RESOURCE_ALREADY_EXISTS`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async generate(request: GenerateLicenceKeyRequest): Promise<LicenceKey> {
		return this.client.call<LicenceKey>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/licence_keys:generate`,
			body: runtime.omit(request, ['parent']),
			bodyType: 'sylphx.money.v1.GenerateLicenceKeyRequest',
			responseType: 'sylphx.money.v1.LicenceKey',
			mutation: true,
		})
	}

	/**
	 * Imports an existing Ed25519 key (PKCS8), for a key already pinned in shipped
	 * clients. Refused unless the expected public key is the imported key's public
	 * half.
	 *
	 * `POST /v1/{parent=orgs/*\/projects/*\/envs/*}/licence_keys:import` · permission `billing:licence_keys.approve` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `UNKNOWN_FIELD`, `RESOURCE_ALREADY_EXISTS`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async import(request: ImportLicenceKeyRequest): Promise<LicenceKey> {
		return this.client.call<LicenceKey>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/licence_keys:import`,
			body: runtime.omit(request, ['parent']),
			bodyType: 'sylphx.money.v1.ImportLicenceKeyRequest',
			responseType: 'sylphx.money.v1.LicenceKey',
			mutation: true,
		})
	}

	/**
	 * Retires a licence key: it stops signing new terms and stays exported for
	 * verification.
	 *
	 * `POST /v1/{name=orgs/*\/projects/*\/envs/*\/licence_keys/*}:retire` · permission `billing:licence_keys.approve` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async retire(request: RetireLicenceKeyRequest): Promise<LicenceKey> {
		return this.client.call<LicenceKey>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/licence_keys/*', 'name')}:retire`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.money.v1.RetireLicenceKeyRequest',
			responseType: 'sylphx.money.v1.LicenceKey',
			mutation: true,
		})
	}

	/**
	 * Gets a licence key (its public half, never the private).
	 *
	 * `GET /v1/{name=orgs/*\/projects/*\/envs/*\/licence_keys/*}` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetLicenceKeyRequest): Promise<LicenceKey> {
		return this.client.call<LicenceKey>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/projects/*/envs/*/licence_keys/*', 'name')}`,
			responseType: 'sylphx.money.v1.LicenceKey',
			mutation: false,
		})
	}

	/**
	 * Lists licence keys, newest first.
	 *
	 * `GET /v1/{parent=orgs/*\/projects/*\/envs/*}/licence_keys` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListLicenceKeysRequest): Promise<ListLicenceKeysResponse> {
		return this.client.call<ListLicenceKeysResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*/projects/*/envs/*', 'parent')}/licence_keys`,
			query: { page_size: request.pageSize, page_token: request.pageToken },
			responseType: 'sylphx.money.v1.ListLicenceKeysResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListLicenceKeysRequest): AsyncGenerator<LicenceKey> {
		let next: ListLicenceKeysRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.licenceKeys ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}
}

